/**
 * @file deepMerge - Deep merge objects utility
 * @module @dsai-io/react/utils/object
 *
 * Enterprise-grade deep object merging with:
 * - Circular reference detection
 * - Maximum depth limits (prevent stack overflow)
 * - Array merge strategies (replace/concat/unique)
 * - Prototype pollution prevention
 * - Pure function (no mutations)
 * - Type-safe with strong inference
 */

import type { DeepMergeOptions } from '../types/shared';

/**
 * Deeply merge two or more objects
 *
 * @param target - Target object
 * @param sources - Source objects to merge into target
 * @param options - Merge options (array strategy, max depth)
 * @returns New merged object (does not mutate inputs)
 *
 * @throws {TypeError} If target or sources contain non-objects
 * @throws {Error} If circular reference detected
 * @throws {Error} If max depth exceeded
 * @throws {Error} If prototype pollution attempted
 *
 * @example
 * ```tsx
 * // Basic merge
 * const result = deepMerge(
 *   { a: 1, b: { c: 2 } },
 *   { b: { d: 3 }, e: 4 }
 * );
 * // => { a: 1, b: { c: 2, d: 3 }, e: 4 }
 *
 * // Array merge strategies
 * deepMerge(
 *   { tags: ['a', 'b'] },
 *   { tags: ['b', 'c'] },
 *   { arrayMergeStrategy: 'replace' }
 * ); // => { tags: ['b', 'c'] }
 *
 * deepMerge(
 *   { tags: ['a', 'b'] },
 *   { tags: ['b', 'c'] },
 *   { arrayMergeStrategy: 'concat' }
 * ); // => { tags: ['a', 'b', 'b', 'c'] }
 *
 * deepMerge(
 *   { tags: ['a', 'b'] },
 *   { tags: ['b', 'c'] },
 *   { arrayMergeStrategy: 'unique' }
 * ); // => { tags: ['a', 'b', 'c'] }
 *
 * // Max depth protection
 * deepMerge(
 *   { a: { b: { c: { d: 1 } } } },
 *   { a: { b: { c: { d: { e: 2 } } } } },
 *   { maxDepth: 3 }
 * ); // Throws Error: Maximum depth exceeded
 *
 * // Prototype pollution prevention
 * deepMerge(
 *   {},
 *   JSON.parse('{"__proto__": {"polluted": true}}')
 * ); // Throws Error: Prototype pollution attempt detected
 * ```
 */
export function deepMerge<T extends Record<string, unknown>>(
  target: T,
  ...sources: Array<Partial<T> | DeepMergeOptions>
): T {
  // Separate options from sources
  const lastArg = sources[sources.length - 1];
  const hasOptions =
    lastArg !== null &&
    typeof lastArg === 'object' &&
    !Array.isArray(lastArg) &&
    ('arrayMergeStrategy' in lastArg ||
      'maxDepth' in lastArg ||
      'allowArrayLengthMismatch' in lastArg);

  const options: DeepMergeOptions = hasOptions ? (sources.pop() as DeepMergeOptions) : {};

  const actualSources = sources as Array<Partial<T>>;

  // Extract options with defaults
  const {
    arrayMergeStrategy = 'replace',
    maxDepth = 10,
    allowArrayLengthMismatch = true,
  } = options;

  // Validate target
  if (target === null || typeof target !== 'object' || Array.isArray(target)) {
    throw new TypeError('deepMerge target must be a non-null object');
  }

  // Clone target to avoid mutation
  const result = { ...target };

  // Track visited objects for circular reference detection
  const visited = new WeakSet<object>();

  /**
   * Check if a key is a dangerous prototype key
   */
  function isDangerousKey(key: string): boolean {
    return key === '__proto__' || key === 'constructor' || key === 'prototype';
  }

  /**
   * Merge value into target at key
   */
  function mergeValue(targetValue: unknown, sourceValue: unknown, currentDepth: number): unknown {
    // Check depth limit
    if (currentDepth > maxDepth) {
      throw new Error(`deepMerge maximum depth (${maxDepth}) exceeded`);
    }

    // Handle null/undefined
    if (sourceValue === null || sourceValue === undefined) {
      return targetValue;
    }

    // Handle primitives
    if (typeof sourceValue !== 'object') {
      return sourceValue;
    }

    // Handle circular references
    if (visited.has(sourceValue as object)) {
      throw new Error('deepMerge circular reference detected');
    }

    // Handle arrays
    if (Array.isArray(sourceValue)) {
      if (!Array.isArray(targetValue)) {
        return [...sourceValue];
      }

      // Check array length mismatch
      if (!allowArrayLengthMismatch && targetValue.length !== sourceValue.length) {
        throw new Error(
          `deepMerge array length mismatch (target: ${targetValue.length}, source: ${sourceValue.length})`
        );
      }

      // Apply array merge strategy
      switch (arrayMergeStrategy) {
        case 'replace':
          return [...sourceValue];

        case 'concat':
          return [...targetValue, ...sourceValue];

        case 'unique': {
          const combined = [...targetValue, ...sourceValue];
          const seen = new Set<string>();
          return combined.filter((item) => {
            const key = JSON.stringify(item);
            if (seen.has(key)) {
              return false;
            }
            seen.add(key);
            return true;
          });
        }

        default:
          return sourceValue;
      }
    }

    // Handle objects
    if (typeof targetValue !== 'object' || targetValue === null || Array.isArray(targetValue)) {
      targetValue = {};
    }

    // Mark as visited
    visited.add(sourceValue as object);

    // Merge object properties
    const merged = { ...(targetValue as Record<string, unknown>) };

    const hasOwn = Object.prototype.hasOwnProperty;
    for (const key in sourceValue) {
      if (hasOwn.call(sourceValue, key)) {
        // Prevent prototype pollution
        if (isDangerousKey(key)) {
          throw new Error(`deepMerge prototype pollution attempt detected: ${key}`);
        }

        const srcValue = (sourceValue as Record<string, unknown>)[key];
        const tgtValue = merged[key as keyof typeof merged];

        (merged as Record<string, unknown>)[key] = mergeValue(tgtValue, srcValue, currentDepth + 1);
      }
    }

    // Unmark after processing
    visited.delete(sourceValue as object);

    return merged;
  }

  // Merge all sources
  const hasOwn = Object.prototype.hasOwnProperty;
  for (const source of actualSources) {
    if (source === null || source === undefined) {
      continue;
    }

    if (typeof source !== 'object' || Array.isArray(source)) {
      throw new TypeError('deepMerge sources must be non-null objects');
    }

    for (const key in source) {
      if (hasOwn.call(source, key)) {
        // Prevent prototype pollution
        if (isDangerousKey(key)) {
          throw new Error(`deepMerge prototype pollution attempt detected: ${key}`);
        }

        const sourceValue = source[key as keyof typeof source];
        const targetValue = result[key as keyof T];

        (result as Record<string, unknown>)[key] = mergeValue(
          targetValue,
          sourceValue,
          0
        ) as T[keyof T];
      }
    }
  }

  return result as T;
}

/**
 * @module @dsai-io/react/utils/object
 * Object manipulation utilities for deep merging, picking, and omitting properties
 */

export { deepMerge } from './deepMerge';
export { omit } from './omit';
export { pick } from './pick';

/**
 * @file omit - Omit object properties utility
 * @module @dsai-io/react/utils/object
 *
 * Enterprise-grade object property omission with:
 * - Type-safe key inference
 * - Readonly preservation
 * - Prototype pollution prevention
 * - Pure function (no mutations)
 * - Handles undefined/null gracefully
 */

/**
 * Omit subset of object properties by keys
 *
 * @param obj - Source object
 * @param keys - Keys to omit from object
 * @returns New object without specified keys
 *
 * @throws {TypeError} If obj is not an object
 * @throws {Error} If prototype pollution attempted
 *
 * @example
 * ```tsx
 * // Basic omit
 * const user = { id: 1, name: 'Alice', password: 'secret', role: 'admin' };
 * const safeUser = omit(user, ['password']);
 * // => { id: 1, name: 'Alice', role: 'admin' }
 *
 * // Type inference
 * const omitted = omit({ a: 1, b: '2', c: true }, ['b']);
 * // Type: { a: number; c: boolean }
 *
 * // Readonly preservation
 * const readonly = { a: 1, b: 2 } as const;
 * const result = omit(readonly, ['b']);
 * // Type: { readonly a: 1 }
 *
 * // Handles missing keys gracefully
 * omit({ a: 1 }, ['a', 'b' as never]);
 * // => {} (both keys omitted, b doesn't exist)
 *
 * // Multiple keys
 * const config = { host: 'localhost', port: 3000, user: 'admin', password: 'secret' };
 * const publicConfig = omit(config, ['user', 'password']);
 * // => { host: 'localhost', port: 3000 }
 *
 * // Prevents prototype pollution
 * omit({}, ['__proto__' as never]);
 * // Throws Error: Prototype pollution attempt detected
 * ```
 */
export function omit<T extends Record<string, unknown>, K extends keyof T>(
  obj: T,
  keys: readonly K[]
): Omit<T, K> {
  // Validate input
  if (obj === null || typeof obj !== 'object' || Array.isArray(obj)) {
    throw new TypeError('omit expects a non-null object as first argument');
  }

  if (!Array.isArray(keys)) {
    throw new TypeError('omit expects an array of keys as second argument');
  }

  // Dangerous keys that could cause prototype pollution
  const dangerousKeys = new Set(['__proto__', 'constructor', 'prototype']);

  // Check for dangerous keys in omit list
  for (const key of keys) {
    if (dangerousKeys.has(String(key))) {
      throw new Error(`omit prototype pollution attempt detected: ${String(key)}`);
    }
  }

  // Create set for O(1) lookup
  const keysToOmit = new Set(keys);

  // Create result object
  const result = {} as Omit<T, K>;

  const hasOwn = Object.prototype.hasOwnProperty;
  // Copy all keys except omitted ones
  for (const key in obj) {
    if (hasOwn.call(obj, key)) {
      if (!keysToOmit.has(key as unknown as K)) {
        (result as Record<string, unknown>)[key as string] = obj[key];
      }
    }
  }

  return result;
}

/**
 * @file pick - Pick object properties utility
 * @module @dsai-io/react/utils/object
 *
 * Enterprise-grade object property picking with:
 * - Type-safe key inference
 * - Readonly preservation
 * - Prototype pollution prevention
 * - Pure function (no mutations)
 * - Handles undefined/null gracefully
 */

/**
 * Pick subset of object properties by keys
 *
 * @param obj - Source object
 * @param keys - Keys to pick from object
 * @returns New object with only specified keys
 *
 * @throws {TypeError} If obj is not an object
 * @throws {Error} If prototype pollution attempted
 *
 * @example
 * ```tsx
 * // Basic pick
 * const user = { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' };
 * const publicUser = pick(user, ['id', 'name']);
 * // => { id: 1, name: 'Alice' }
 *
 * // Type inference
 * const picked = pick({ a: 1, b: '2', c: true }, ['a', 'c']);
 * // Type: { a: number; c: boolean }
 *
 * // Readonly preservation
 * const readonly = { a: 1, b: 2 } as const;
 * const result = pick(readonly, ['a']);
 * // Type: { readonly a: 1 }
 *
 * // Handles missing keys gracefully
 * pick({ a: 1 }, ['a', 'b' as never]);
 * // => { a: 1 } (b is not in result)
 *
 * // Prevents prototype pollution
 * pick({}, ['__proto__' as never]);
 * // Throws Error: Prototype pollution attempt detected
 * ```
 */
export function pick<T extends Record<string, unknown>, K extends keyof T>(
  obj: T,
  keys: readonly K[]
): Pick<T, K> {
  // Validate input
  if (obj === null || typeof obj !== 'object' || Array.isArray(obj)) {
    throw new TypeError('pick expects a non-null object as first argument');
  }

  if (!Array.isArray(keys)) {
    throw new TypeError('pick expects an array of keys as second argument');
  }

  // Create result object
  const result = {} as Pick<T, K>;

  // Dangerous keys that could cause prototype pollution
  const dangerousKeys = new Set(['__proto__', 'constructor', 'prototype']);

  // Pick specified keys
  for (const key of keys) {
    // Prevent prototype pollution
    if (dangerousKeys.has(String(key))) {
      throw new Error(`pick prototype pollution attempt detected: ${String(key)}`);
    }

    const hasOwn = Object.prototype.hasOwnProperty;
    // Only copy if key exists in source object (own property)
    if (hasOwn.call(obj, key)) {
      (result as Record<string, unknown>)[key as string] = obj[key];
    }
  }

  return result;
}
